import{_ as a,a as t,o as s,a4 as r}from"./chunks/framework.-FZumj2l.js";const g=JSON.parse('{"title":"Build an Admin Dashboard","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/admin/build-an-admin-dashboard.md","filePath":"api/workflows/admin/build-an-admin-dashboard.md","lastUpdated":1784902076000}'),i={name:"api/workflows/admin/build-an-admin-dashboard.md"};function o(n,e,d,l,c,h){return s(),t("div",null,e[0]||(e[0]=[r('<h1 id="build-an-admin-dashboard" tabindex="-1">Build an Admin Dashboard <a class="header-anchor" href="#build-an-admin-dashboard" aria-label="Permalink to &quot;Build an Admin Dashboard&quot;">​</a></h1><p>The <strong>complete admin blueprint</strong> — every admin-panel menu mapped to its Admin API. The API mirrors the admin panel menu-for-menu, so any back-office screen can be rebuilt from it. Use this as the map; for the two flows with real sequencing/structure gotchas, see <a href="/api/workflows/admin/create-order-flow.html">Create-Order</a> and <a href="/api/workflows/admin/product-management.html">Product Management</a>.</p><p>Every request carries the admin Integration token:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</span></span></code></pre></div><h2 id="agent-ask-inputs" tabindex="-1">Agent-ask inputs <a class="header-anchor" href="#agent-ask-inputs" aria-label="Permalink to &quot;Agent-ask inputs&quot;">​</a></h2><ul><li><strong>Integration token</strong> — ask the user; generated in the admin panel&#39;s Integration menu. No admin login; never mint it.</li><li><strong>Server URL</strong> — ask the user for their Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>) and prefix every endpoint path with it. Never assume localhost or a demo domain.</li></ul><h2 id="the-pattern-behind-every-screen" tabindex="-1">The pattern behind every screen <a class="header-anchor" href="#the-pattern-behind-every-screen" aria-label="Permalink to &quot;The pattern behind every screen&quot;">​</a></h2><p><strong>list → detail → action</strong> — a <code>{ data, meta }</code> listing (<code>?page</code> + <code>?per_page</code> + filters), a detail GET with relations embedded, then create/update/delete + per-record actions (each permission-gated → <code>403</code> if the token&#39;s role lacks it). See the <a href="/api/workflows/admin/">Admin Workflows overview</a> for the envelope, pagination headers, and GraphQL rules.</p><h2 id="_1-dashboard-reporting" tabindex="-1">1. Dashboard &amp; Reporting <a class="header-anchor" href="#_1-dashboard-reporting" aria-label="Permalink to &quot;1. Dashboard &amp; Reporting&quot;">​</a></h2><ul><li><strong><a href="/api/rest-api/admin/dashboard/">Dashboard</a></strong> — the headline stats behind the admin home (<code>?type=</code> picks a stat group; <code>?start</code>/<code>?end</code>/<code>?channel</code> bound the window).</li><li><strong><a href="/api/rest-api/admin/reporting/">Reporting</a></strong> — sales / customers / products report groups, a table &quot;view details&quot; mode, and CSV export.</li></ul><h2 id="_2-sales" tabindex="-1">2. Sales <a class="header-anchor" href="#_2-sales" aria-label="Permalink to &quot;2. Sales&quot;">​</a></h2><p>The order lifecycle and its documents:</p><ul><li><strong><a href="/api/rest-api/admin/sales/orders/">Orders</a></strong> — list + detail (customer, addresses, type-aware items, invoices, shipments, refunds, payment, totals — all embedded), plus per-order <strong>actions</strong>: cancel, create invoice / shipment / refund, add comment. Eligibility + gotchas: fulfillment actions each have their own guards.</li><li><strong><a href="/api/rest-api/admin/sales/invoices/">Invoices</a></strong> · <strong><a href="/api/rest-api/admin/sales/shipments/">Shipments</a></strong> · <strong><a href="/api/rest-api/admin/sales/refunds/">Refunds</a></strong> — the document datagrids (list, detail, export; invoice print PDF + mass-update-status).</li><li><strong><a href="/api/rest-api/admin/sales/transactions/list.html">Transactions</a></strong> — payment records; includes Record-Payment create.</li><li><strong><a href="/api/rest-api/admin/sales/bookings/">Bookings</a></strong> — bookable-product reservations (read-only).</li><li><strong><a href="/api/workflows/admin/create-order-flow.html">Create-Order flow →</a></strong> — place an order for a customer through a draft cart.</li></ul><h2 id="_3-catalog" tabindex="-1">3. Catalog <a class="header-anchor" href="#_3-catalog" aria-label="Permalink to &quot;3. Catalog&quot;">​</a></h2><ul><li><strong><a href="/api/rest-api/admin/catalog/products/">Products</a></strong> — the datagrid, CRUD, copy, mass-actions, export, and the image/inventory/price sub-panels. The two-step create + partial-update traps live in <strong><a href="/api/workflows/admin/product-management.html">Product Management →</a></strong>.</li><li><strong><a href="/api/rest-api/admin/catalog/categories/">Categories</a></strong> — flat datagrid + nested tree; CRUD (move = update with <code>parent_id</code>+<code>position</code>); mass-actions; root-category delete guards.</li><li><strong><a href="/api/rest-api/admin/catalog/attributes/">Attributes</a></strong> — the dynamic fields + their options sub-resource; system-attribute + in-use guards.</li><li><strong><a href="/api/rest-api/admin/catalog/families/">Attribute Families</a></strong> — attribute groupings chosen at product-create; last-family / product-attached delete guards.</li></ul><h2 id="_4-customers" tabindex="-1">4. Customers <a class="header-anchor" href="#_4-customers" aria-label="Permalink to &quot;4. Customers&quot;">​</a></h2><ul><li><strong><a href="/api/rest-api/admin/customers/">Customers</a></strong> — list/detail/CRUD, addresses, notes, <strong>impersonate</strong> (&quot;login as customer&quot; → a short-lived customer token), mass-actions; groups; reviews moderation; GDPR requests. Delete is guarded when the customer has active orders.</li></ul><h2 id="_5-marketing" tabindex="-1">5. Marketing <a class="header-anchor" href="#_5-marketing" aria-label="Permalink to &quot;5. Marketing&quot;">​</a></h2><ul><li><strong><a href="/api/rest-api/admin/marketing/">Marketing</a></strong> — Cart Rules (+ coupons: single/bulk-generate/mass-delete), Catalog Rules, Email Templates, Events, Campaigns (+ send), Newsletter Subscribers, Search Terms, Search Synonyms, URL Rewrites, Sitemaps (+ generate).</li></ul><h2 id="_6-cms" tabindex="-1">6. CMS <a class="header-anchor" href="#_6-cms" aria-label="Permalink to &quot;6. CMS&quot;">​</a></h2><ul><li><strong><a href="/api/rest-api/admin/cms/pages/">CMS Pages</a></strong> — list/detail/CRUD + mass-delete. Create broadcasts to every locale; update is <strong>locale-nested</strong>.</li></ul><h2 id="_7-settings" tabindex="-1">7. Settings <a class="header-anchor" href="#_7-settings" aria-label="Permalink to &quot;7. Settings&quot;">​</a></h2><p>Reference data and access control — mostly straight CRUD (+ mass-delete where the panel has it), each with its own delete guards (last-of-kind, in-use):</p><ul><li><strong><a href="/api/rest-api/admin/settings/currencies/list.html">Currencies</a></strong> · <strong><a href="/api/rest-api/admin/settings/locales/list.html">Locales</a></strong> · <strong><a href="/api/rest-api/admin/settings/exchange-rates/list.html">Exchange Rates</a></strong> · <strong><a href="/api/rest-api/admin/settings/channels/list.html">Channels</a></strong></li><li><strong><a href="/api/rest-api/admin/settings/inventory-sources/list.html">Inventory Sources</a></strong> · <strong><a href="/api/rest-api/admin/settings/tax-rates/list.html">Tax Rates</a></strong> · <strong><a href="/api/rest-api/admin/settings/tax-categories/list.html">Tax Categories</a></strong></li><li><strong><a href="/api/rest-api/admin/settings/users/list.html">Users</a></strong> · <strong><a href="/api/rest-api/admin/settings/roles/list.html">Roles</a></strong> · <strong><a href="/api/rest-api/admin/settings/themes/list.html">Themes</a></strong> · <strong><a href="/api/rest-api/admin/settings/data-transfer-imports/">Data Transfer Imports</a></strong></li></ul><h2 id="_8-configuration" tabindex="-1">8. Configuration <a class="header-anchor" href="#_8-configuration" aria-label="Permalink to &quot;8. Configuration&quot;">​</a></h2><ul><li><strong><a href="/api/rest-api/admin/configuration/">Configuration</a></strong> — the whole <code>core_config</code> key/value store via three generic endpoints (menu schema, read values by slug, update by slug). Writes are scoped to the slug — a key outside it is rejected.</li></ul><h2 id="graphql-variant" tabindex="-1">GraphQL variant <a class="header-anchor" href="#graphql-variant" aria-label="Permalink to &quot;GraphQL variant&quot;">​</a></h2><p>Every menu is available at <code>POST /api/admin/graphql</code> (admin token, no storefront key). Remember the <strong>result-field / <code>id</code> rule</strong> on action + mass-action mutations (select <code>success</code> / <code>message</code> / <code>orderId</code> / … — not a generic <code>id</code>). Details in the <a href="/api/workflows/admin/#graphql-the-must-know-rules">Admin Workflows overview</a>.</p><h2 id="status-codes-to-handle" tabindex="-1">Status codes to handle <a class="header-anchor" href="#status-codes-to-handle" aria-label="Permalink to &quot;Status codes to handle&quot;">​</a></h2><p><code>200/201</code> success · <code>401</code> unauthenticated · <code>403</code> forbidden (permission) · <code>400</code> bad input / guard · <code>404</code> not found · <code>409</code> wrong step order (Create-Order) · <code>422</code> validation / ineligible action.</p>',30)]))}const m=a(i,[["render",o]]);export{g as __pageData,m as default};
